def base62_decode(s, alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"):
    num = 0
    for char in s:
        num = num * 62 + alphabet.index(char)
    return num.to_bytes((num.bit_length() + 7) // 8, 'big').decode('utf-8')

